input.query:
alter table api.company add column if not exists ref_key uuid;
create unique index if not exists company_ref_key_idx on api.company(ref_key);
update api.company set ref_key='58009517-9772-57c0-8c12-180dc192012c' where inn='7700001009';
update api.company set ref_key='0221ab04-86e6-5a00-8275-e75cc0af4ebe' where inn='7700002018';
update api.company set ref_key='b7da7363-223d-57d3-b23b-1e939f613502' where inn='7700003027';

update api.app_user set role='lawyer' where login='lawyer1';

create table api.contract(
 id serial primary key,
 number text not null unique,
 application_id integer not null references api.application(id),
 amount numeric not null check (amount>0),
 signed_on date,
 status text not null default 'Проект' check (status in ('Проект','Подписан'))
);

create function priv.contract_company(app int) returns int language sql stable security definer set search_path=api as
$$ select company_id from api.application where id=app $$;

create function priv.check_contract() returns trigger language plpgsql security definer set search_path=api as $$
begin
 if not exists (select 1 from api.application a join api.status s on s.id=a.status_id where a.id=new.application_id and s.name='Одобрена') then
  raise exception 'Договор можно заключить только по одобренной заявке';
 end if;
 return new;
end $$;
create trigger contract_check before insert or update on api.contract for each row execute function priv.check_contract();

alter table api.contract enable row level security;
create policy admin_all on api.contract for all to fund_admin using (true) with check (true);
create policy lawyer_all on api.contract for all to lawyer using (true) with check (true);
create policy applicant_read on api.contract for select to applicant using (priv.contract_company(application_id)=priv.my_company());

grant select,insert,update,delete on api.contract to fund_admin, lawyer;
grant select on api.contract to applicant;
grant usage on schema api, priv to lawyer;
grant usage on sequence api.contract_id_seq to fund_admin, lawyer;
grant select on api.company, api.status, api.application to lawyer;
create policy lawyer_read on api.application for select to lawyer using (true);

create view api.limit_balance with (security_invoker=false) as
select c.name as company, c.funding_limit, ap.approved, coalesce(ct.contracted,0) as contracted,
 c.funding_limit - coalesce(ct.contracted,0) as remaining
from api.company c
join (select a.company_id, sum(a.amount) approved from api.application a join api.status s on s.id=a.status_id where s.name='Одобрена' group by 1) ap on ap.company_id=c.id
left join (select a.company_id, sum(k.amount) contracted from api.contract k join api.application a on a.id=k.application_id group by 1) ct on ct.company_id=c.id;
revoke all on api.limit_balance from public, anon, applicant, expert;
grant select on api.limit_balance to fund_admin, lawyer;
notify pgrst,'reload schema';

